/**
 * Claude projection v2 (#2442): one version bump for member subagents, skills and the opt-in
 * `settings.json` hooks, and byte-preserving rollback for every file v2 writes (harness-adapters §15.7).
 *
 * Each rollback test snapshots the whole tree before install and requires the exact same bytes after
 * install → upgrade → rollback: no generated file left behind, no user byte changed.
 */
import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {
  CLAUDE_PROJECTION_VERSION,
  installClients,
  uninstallClients,
} from '../packages/squad-sdk/src/client/adapters/index.js';

const MCP = { command: 'squad', args: ['state-mcp'] };
const V1_NOTE = '<!-- Generated by Squad. Managed file: refreshed by `squad upgrade`; edit .squad/ instead. -->';

let root: string;

function write(rel: string, content: string): void {
  fs.mkdirSync(path.dirname(path.join(root, rel)), { recursive: true });
  fs.writeFileSync(path.join(root, rel), content);
}

/** Every file under root, relative path → bytes (base64), plus the directory set. */
function snapshot(): { files: Record<string, string>; dirs: string[] } {
  const files: Record<string, string> = {};
  const dirs: string[] = [];
  const walk = (dir: string) => {
    for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
      const abs = path.join(dir, e.name);
      const rel = path.relative(root, abs).split(path.sep).join('/');
      if (e.isDirectory()) {
        dirs.push(rel);
        walk(abs);
      } else files[rel] = fs.readFileSync(abs).toString('base64');
    }
  };
  walk(root);
  return { files, dirs: dirs.sort() };
}

/** Team inputs that make v2 project every kind of file: members, template skills and hooks. */
function seedTeam(): void {
  write('.squad/team.md', '# Team\n');
  write('.squad/agents/dallas/charter.md', '# Dallas — Backend Dev\n\n## Identity\n- **ID:** `dallas`\n\n## Model\n- **Preferred:** sonnet\n');
  write('.squad/agents/scribe/charter.md', '# Scribe\n\n## Identity\n- **ID:** `scribe`\n');
  write('.squad/templates/skills/git-workflow/SKILL.md', '---\nname: "git-workflow"\ndescription: "Branching"\n---\n\nUse branches.\n');
  write('.squad/templates/skills/distributed-mesh/SKILL.md', '---\nname: "distributed-mesh"\ndescription: "Mesh"\n---\n\nSync.\n');
  write('.squad/templates/skills/distributed-mesh/sync-mesh.sh', 'echo hi\n');
  write('.squad/config.json', `${JSON.stringify({ claudeHooks: 'advisory' }, null, 2)}\n`);
}

function generatedMarkdown(): string[] {
  return Object.keys(snapshot().files).filter((f) => f.startsWith('.claude/') && f.endsWith('.md'));
}

beforeEach(() => {
  root = fs.mkdtempSync(path.join(os.tmpdir(), 'squad-claude-v2-'));
  seedTeam();
});
afterEach(() => fs.rmSync(root, { recursive: true, force: true }));

describe('Claude projection v2: version', () => {
  it('is bumped once, to v2', () => {
    expect(CLAUDE_PROJECTION_VERSION).toBe(2);
  });

  it('stamps the coordinator, every member and every skill', () => {
    installClients(['claude'], { root, mcp: MCP });
    const md = generatedMarkdown();
    expect(md).toEqual(expect.arrayContaining(['.claude/agents/squad.md', '.claude/agents/dallas.md', '.claude/agents/scribe.md', '.claude/skills/git-workflow/SKILL.md']));
    for (const f of md) expect(fs.readFileSync(path.join(root, f), 'utf8'), f).toContain('Claude projection v2.');
  });

  it('upgrades v1 files in place: the old note still marks them as Squad-owned', () => {
    write('.claude/agents/squad.md', `---\nname: squad\n---\n${V1_NOTE}\n\nold coordinator\n`);
    write('.claude/agents/dallas.md', `---\nname: dallas\n---\n${V1_NOTE}\n\nold member\n`);
    const results = installClients(['claude'], { root, mcp: MCP });
    for (const p of ['.claude/agents/squad.md', '.claude/agents/dallas.md']) {
      expect(results.find((r) => r.path === p)?.action, p).toBe('updated');
      expect(fs.readFileSync(path.join(root, p), 'utf8')).toContain('Claude projection v2.');
    }
    uninstallClients(['claude'], { root, mcp: MCP });
    expect(fs.existsSync(path.join(root, '.claude'))).toBe(false);
  });
});

describe('Claude projection v2: byte-preserving rollback (§15.7)', () => {
  it('a fresh repo returns to exactly its pre-install tree', () => {
    const before = snapshot();
    installClients(['claude'], { root, mcp: MCP });
    installClients(['claude'], { root, mcp: MCP }); // upgrade over itself
    expect(fs.existsSync(path.join(root, '.claude/settings.json'))).toBe(true);
    uninstallClients(['claude'], { root, mcp: MCP });
    expect(snapshot()).toEqual(before);
  });

  it('keeps every user byte in each file v2 shares with the user', () => {
    write('CLAUDE.md', '# My project\r\n\r\nUse pnpm.'); // CRLF, no trailing newline
    write('.gitignore', 'node_modules/\n.env\n');
    write('.mcp.json', `${JSON.stringify({ mcpServers: { github: { command: 'gh-mcp', args: [] } } }, null, 2)}\n`);
    write(
      '.claude/settings.json',
      `${JSON.stringify(
        {
          permissions: { allow: ['Bash(npm test:*)'] },
          hooks: { PreToolUse: [{ matcher: 'Bash', hooks: [{ type: 'command', command: 'audit.sh' }] }] },
        },
        null,
        2,
      )}\n`,
    );
    // User-authored agents and skills, including ones at paths v2 would generate.
    write('.claude/agents/reviewer.md', '---\nname: reviewer\n---\nMine.\n');
    write('.claude/agents/dallas.md', '---\nname: dallas\n---\nHand-written Dallas.\n');
    write('.claude/skills/mine/SKILL.md', '---\nname: mine\n---\nMy skill.\n');
    write('.claude/skills/git-workflow/SKILL.md', '---\nname: git-workflow\n---\nMy workflow.\n');
    const before = snapshot();

    const install = installClients(['claude'], { root, mcp: MCP });
    for (const p of ['.claude/agents/dallas.md', '.claude/skills/git-workflow/SKILL.md']) {
      expect(install.find((r) => r.path === p)?.action, p).toBe('skipped');
    }
    expect(fs.readFileSync(path.join(root, '.claude/agents/scribe.md'), 'utf8')).toContain('Claude projection v2.');
    installClients(['claude'], { root, mcp: MCP });

    uninstallClients(['claude'], { root, mcp: MCP });
    expect(snapshot()).toEqual(before);
  });

  it('turning hooks off on upgrade, then rolling back, still restores the original bytes', () => {
    write('.claude/settings.json', '{\n  "model": "opus"\n}\n');
    const before = snapshot();
    installClients(['claude'], { root, mcp: MCP });
    write('.squad/config.json', `${JSON.stringify({ claudeHooks: 'off' }, null, 2)}\n`);
    installClients(['claude'], { root, mcp: MCP });
    write('.squad/config.json', `${JSON.stringify({ claudeHooks: 'advisory' }, null, 2)}\n`);
    uninstallClients(['claude'], { root, mcp: MCP });
    expect(snapshot()).toEqual(before);
  });
});
